// cart
const getCart=()=>ld('cart',[]);
const cnt=()=>getCart().reduce((s,x)=>s+x.q,0);
const updateCartCount=()=>document.querySelectorAll('.cnt').forEach(e=>e.textContent=cnt());
const saveCart=c=>{sv('cart',c);updateCartCount()};
const addToCart=id=>{const c=getCart(),i=c.find(x=>x.id==id);i?i.q++:c.push({id:+id,q:1});saveCart(c)};
const removeFromCart=id=>saveCart(getCart().filter(x=>x.id!=id));
const setQty=(id,d)=>{const c=getCart(),i=c.find(x=>x.id==id);if(!i)return;i.q+=d;saveCart(i.q<1?c.filter(x=>x!==i):c)};
const calculateCartTotal=(c=getCart())=>{const sub=c.reduce((s,x)=>s+prod(x.id)[3]*x.q,0),ship=!sub||sub>=CFG.free?0:CFG.ship;return{sub,ship,total:sub+ship}};
// session (Supabase Auth) / commandes
let U=null,ORD=[];
const getCurrentUser=()=>U;
async function refreshUser(){const o=U&&U.id;U=await shop.currentUser();return (U&&U.id)!==o}
const logout=async()=>{await shop.signOut();U=null;ORD=[];go('home')};
// Le catalogue Supabase remplace le catalogue local (qui reste en secours hors ligne)
async function syncCatalog(){const r=await shop.products();if(!r.ok||!r.data.length)return;P.length=0;
 r.data.forEach(x=>{P.push([x.id,x.category,[x.name,x.name_en||x.name],x.price_millimes/1000]);DS[x.id]=[x.description,x.description_en||x.description];
 if(x.image_url&&/^(https:\/\/|images\/)/.test(x.image_url))IMG[x.id]=x.image_url});
 saveCart(getCart().filter(c=>prod(c.id)))}
// ui helpers
const seo=(a,b)=>{document.title=a+' | Maison L’kam';document.querySelector('meta[name=description]').content=b};
const er=m=>{const e=document.getElementById('err');if(e)e.textContent=m};
const fmt=n=>n.toFixed(2)+' TND';
const thr=()=>L==='fr'?`Livraison ${CFG.ship} TND, offerte dès ${CFG.free} TND.`:`Shipping ${CFG.ship} TND, free over ${CFG.free} TND.`;
const fld=(n,l,ty='text',v='')=>`<label for="${n}">${l}</label><input id="${n}" name="${n}" type="${ty}" value="${esc(v)}" required>`;
const bc=a=>`<p class="bc">${a.map(([n,r,x])=>r?`<a href="#" data-go="${r}" data-a="${x||''}">${n}</a>`:`<span aria-current="page">${n}</span>`).join(' › ')}</p>`;
const card=p=>`<div class="card"><div class="img" data-go="prod" data-a="${p[0]}">${ico(p[0])}</div><h3>${nm(p[2])}</h3><span class="m">${nm(cat(p[1]).n)}</span><span class="pr">${fmt(p[3])}</span><p class="m">${nm(DS[p[0]])}</p><div><a class="btn o" href="#" data-go="prod" data-a="${p[0]}">${t('view')}</a> <button class="btn" data-add="${p[0]}">${t('add')}</button></div></div>`;
const cc=c=>`<div class="card"><div class="img k-${c.id}" data-go="cat" data-a="${c.id}">${CI[c.id]?`<img class="ci" src="${CI[c.id]}" alt="${esc(nm(c.n))}">`:c.m}</div><h3>${nm(c.n)}</h3><p class="m">${nm(c.s)}</p><div><a class="btn o" href="#" data-go="cat" data-a="${c.id}">${t('disc')}</a></div></div>`;
const sum=k=>`<div class="row"><span>${t('sub')}</span><b>${fmt(k.sub)}</b></div><div class="row"><span>${t('ship')}</span><b>${k.ship?fmt(k.ship):t('free')}</b></div><div class="row"><span>${t('total')}</span><b class="pr">${fmt(k.total)}</b></div><p class="m">${thr()}</p>`;
const head=()=>`<header><a class="logo" href="#" data-go="home">MAISON L’KAM</a><nav><a class="lk" href="#" data-go="home">${t('home')}</a><a class="lk" href="#" data-go="shop">${t('shop')}</a><details><summary class="lk">${t('cats')} ▾</summary><div>${C.map(c=>`<a class="lk" href="#" data-go="cat" data-a="${c.id}">${nm(c.n)}</a>`).join('')}</div></details></nav><button class="lk" data-lang="1" aria-label="Language">${L==='fr'?'EN':'FR'}</button><a class="lk" href="#" data-go="account">${t('acct')}</a>${U&&U.admin?'<a class="lk" href="admin.html">Admin</a>':''}<a class="lk" href="#" data-go="cart">${t('cart')}<span class="cnt">${cnt()}</span></a></header>`;
const V={
home:()=>{seo(t('home'),t('tag'));return `<section class="hero"><p class="m">${t('men')}</p><h1>${t('hero')}</h1><p class="m">${t('tag')}</p><p><a class="btn" href="#" data-go="shop">${t('shop')}</a></p></section><h2>${t('ourcats')}</h2><div class="grid">${C.map(cc).join('')}</div><h2>${t('feat')}</h2><div class="grid">${[2,5,7,10].map(i=>card(prod(i))).join('')}</div>`},
shop:()=>{seo(t('shop'),t('tag'));const l=P.filter(p=>!A||p[1]===A);return `<h1>${t('shop')}</h1><h2>${t('explore')}</h2><div class="grid">${C.map(cc).join('')}</div><p>${[['',t('all')],...C.map(c=>[c.id,nm(c.n)])].map(([i,n])=>`<a class="btn o" href="#" data-go="shop" data-a="${i}">${n}</a>`).join(' ')}</p><div class="grid">${l.map(card).join('')}</div>`},
cat:()=>{const c=cat(A),i=C.indexOf(c),l=P.filter(p=>p[1]===A),o=[C[(i+1)%C.length],C[(i+2)%C.length]];seo(nm(c.n),nm(c.s));return `${bc([[t('home'),'home'],[t('shop'),'shop'],[nm(c.n)]])}<h1>${nm(c.n)}</h1><p class="m">${nm(c.s)}</p><div class="grid">${l.length?l.map(card).join(''):`<p>${t('none')}</p>`}</div><h2>${t('also')}</h2><div class="grid">${o.map(cc).join('')}</div>`},
prod:()=>{const p=prod(A),c=cat(p[1]);seo(nm(p[2]),nm(c.s));return `${bc([[t('home'),'home'],[nm(c.n),'cat',c.id],[nm(p[2])]])}<div class="two"><div class="img" style="cursor:default">${ico(p[0])}</div><div><h1>${nm(p[2])}</h1><p class="m">${nm(c.s)}</p><p>${nm(DS[p[0]])}</p><p class="pr" style="font-size:26px">${fmt(p[3])}</p><p class="m">${thr()}</p><button class="btn" data-add="${p[0]}">${t('add')}</button></div></div>`},
cart:()=>{seo(t('myc'),t('tag'));const c=getCart();if(!c.length)return `<h1>${t('myc')}</h1><p>${t('empty')}</p><a class="btn" href="#" data-go="shop">${t('cont')}</a>`;
return `<h1>${t('myc')}</h1>`+c.map(x=>{const p=prod(x.id);return `<div class="row"><span>${nm(p[2])}<br><small class="m">${nm(cat(p[1]).n)} · ${fmt(p[3])}</small></span><span><button class="btn o" data-q="${p[0]},-1" aria-label="−">−</button> ${x.q} <button class="btn o" data-q="${p[0]},1" aria-label="+">+</button> <button class="btn o" data-rm="${p[0]}" aria-label="Remove">✕</button></span><b>${fmt(p[3]*x.q)}</b></div>`}).join('')+sum(calculateCartTotal(c))+`<p><button class="btn" data-go="checkout">${t('go')}</button></p>`},
login:()=>{seo(t('login'),t('login'));return `<div class="f"><h1>${t('login')}</h1><form data-f="log">${fld('email',t('email'),'email')}${fld('pw',t('pw'),'password')}<p class="m">${t('demo')}</p><p id="err" class="err" role="alert"></p><button class="btn">${t('login')}</button></form><p><a href="#" data-go="register">${t('noacc')}</a> · <a href="#" data-msg="forgotm">${t('forgot')}</a></p></div>`},
register:()=>{seo(t('reg'),t('reg'));return `<div class="f"><h1>${t('reg')}</h1><form data-f="reg">${fld('fn',t('fn'))}${fld('ln',t('ln'))}${fld('email',t('email'),'email')}${fld('pw',t('pw'),'password')}${fld('pw2',t('pw2'),'password')}<p class="m">${t('demo')}</p><label><input type="checkbox" name="terms" required>${t('terms')}</label><p id="err" class="err" role="alert"></p><button class="btn">${t('reg')}</button></form><p><a href="#" data-go="login">${t('have')}</a></p></div>`},
verify:()=>{seo(t('vt'),t('vp'));return `<div class="f"><h1>${t('vt')}</h1><p>${t('vp')}</p><a class="btn" href="#" data-go="login">${t('login')}</a></div>`},
account:()=>{const u=getCurrentUser();seo(t('acct'),t('acct'));return `<h1>${t('hello')}, ${esc(u.fn)}</h1><h2>${t('info')}</h2><div class="row"><span>${esc(u.fn)} ${esc(u.ln)}</span><span>${esc(u.email)}</span></div><h2>${t('orders')}</h2><p class="m">${L==='fr'?'Vos 100 dernières commandes sont affichées.':'Your last 100 orders are shown.'}</p>${ORD.length?ORD.map(x=>`<div class="row"><b>${esc(x.ref)}</b><span>${new Date(x.created_at).toLocaleString()}</span><span>${x.items.reduce((s,i)=>s+i.qty,0)} ${t('items')}</span><span>${fmt(x.total/1000)}</span><span class="m">${esc(x.status)}</span></div>`).join(''):`<p class="m">${t('noord')}</p>`}<p><button class="btn o" data-out="1">${t('out')}</button></p>`},
checkout:()=>{const u=getCurrentUser(),c=getCart();seo(t('go'),t('pay'));return `<h1>${t('go')}</h1><div class="two"><form data-f="chk"><h2>${t('shiph')}</h2>${fld('fn',t('fn'),'text',u.fn)}${fld('ln',t('ln'),'text',u.ln)}${fld('email',t('email'),'email',u.email)}${fld('phone',t('phone'),'tel')}${fld('addr',t('addr'))}${fld('city',t('city'))}${fld('zip',t('zip'))}${fld('country',t('ctry'),'text',L==='fr'?'Tunisie':'Tunisia')}<h2>${t('pay')}</h2><p><label><input type="radio" name="pay" value="card" checked>${t('card')} · **** **** **** 4242</label></p><p><label><input type="radio" name="pay" value="cod">${t('cod')}</label></p><p class="ok">${t('nopay')}</p><p id="err" class="err" role="alert"></p><button class="btn">${t('sim')}</button></form><div><h2>${t('summ')}</h2>${c.map(x=>{const p=prod(x.id);return `<div class="row"><span>${nm(p[2])} × ${x.q}</span><span>${fmt(p[3]*x.q)}</span></div>`}).join('')}${sum(calculateCartTotal(c))}</div></div>`},
done:()=>{const x=ORD.find(o=>o.ref===A);if(!x)return `<p>${t('none')}</p>`;seo(t('thanks'),t('thx'));const s=x.ship_to||{};return `<div class="f"><h1>${t('thanks')}</h1><p>${t('thx')}</p><div class="row"><span>${t('ref')}</span><b>${esc(x.ref)}</b></div><div class="row"><span>${t('date')}</span><span>${new Date(x.created_at).toLocaleString()}</span></div>${x.items.map(i=>`<div class="row"><span>${esc(L==='fr'?i.name:(i.name_en||i.name))} × ${i.qty}</span><span>${fmt(i.unit_price*i.qty/1000)}</span></div>`).join('')}<div class="row"><span>${t('total')}</span><b class="pr">${fmt(x.total/1000)}</b></div><p class="m">${esc([s.name,s.addr,s.zip,s.city,s.country].join(', '))}</p><p class="ok">${t('nopay2')}</p><a class="btn" href="#" data-go="home">${t('back')}</a> <a class="btn o" href="#" data-go="account">${t('mine')}</a></div>`}};
function render(){document.documentElement.lang=L;document.getElementById('app').innerHTML=head()+`<main>${flash?`<p class="ok">${flash}</p>`:''}${V[R]()}</main><footer>${t('foot')}</footer>`;flash=''}
async function go(r,a){ // guard: client-side only, not real security
 if((r==='account'||r==='checkout')&&!getCurrentUser()){next=r;flash=t('needlog');r='login'}
 if(r==='checkout'&&!getCart().length)r='cart';
 R=r;A=a||null;if(R==='account'||R==='done'){const x=await shop.myOrders(U.id);ORD=x.ok?x.data:[];if(!x.ok)flash=x.error}render();scrollTo(0,0)}
const F={
reg:async f=>{const em=f.email.trim().toLowerCase();
 if(!f.fn.trim()||!f.ln.trim()||!em||!f.pw)return er(t('e_req'));
 if(!/^\S+@\S+\.\S+$/.test(em))return er(t('e_mail'));
 if(f.pw.length<6)return er(t('e_len'));if(f.pw!==f.pw2)return er(t('e_match'));
 if(!f.terms)return er(t('e_terms'));
 const r=await shop.signUp(em,f.pw,f.fn.trim(),f.ln.trim(),next);if(!r.ok)return er(r.error);go('verify')},
log:async f=>{const r=await shop.signIn(f.email.trim().toLowerCase(),f.pw);if(!r.ok)return er(r.error);
 await refreshUser();const n=next;next=null;go(n||'account')},
chk:async f=>{const c=getCart(),u=getCurrentUser();if(!c.length||!u)return go('cart');
 const k=calculateCartTotal(c),sig=JSON.stringify(c);let a=ld('attempt',null);
 if(!a||a.sig!==sig){a={id:crypto.randomUUID(),sig};sv('attempt',a)} // meme tentative = pas de doublon apres coupure reseau
 const r=await shop.createOrder({attempt:a.id,items:c.map(x=>({id:x.id,q:x.q})),expected:Math.round(k.total*1000),
  ship:{name:`${f.fn} ${f.ln}`,email:f.email,phone:f.phone,addr:f.addr,city:f.city,zip:f.zip,country:f.country},pay:f.pay});
 if(!r.ok)return er(r.error);
 sv('attempt',null);saveCart([]);go('done',r.data.ref)}};
document.addEventListener('click',e=>{const el=e.target.closest('[data-go],[data-add],[data-q],[data-rm],[data-lang],[data-out],[data-msg]');if(!el)return;e.preventDefault();const d=el.dataset;
 if(d.go)go(d.go,d.a);
 else if(d.add){addToCart(d.add);const o=el.textContent;el.textContent='✓';setTimeout(()=>el.textContent=o,900)}
 else if(d.q){const[i,n]=d.q.split(',');setQty(i,+n);render()}
 else if(d.rm){removeFromCart(d.rm);render()}
 else if(d.lang){L=L==='fr'?'en':'fr';sv('lang',L);render()}
 else if(d.out)logout();
 else if(d.msg)er(t(d.msg))});
document.addEventListener('submit',async e=>{e.preventDefault();const h=F[e.target.dataset.f];if(!h||busy)return;busy=true;const bs=e.target.querySelectorAll('button');bs.forEach(b=>b.disabled=true);
 try{await h(Object.fromEntries(new FormData(e.target)))}catch(x){er('Erreur réseau, réessayez.')}finally{busy=false;bs.forEach(b=>b.disabled=false)}});
(async()=>{await refreshUser();await syncCatalog();
 const q=new URLSearchParams(location.search).get('next');
 // retour au checkout apres confirmation e-mail
 if(U&&q==='checkout'){history.replaceState(null,'',location.pathname);return go('checkout')}
 shop.onAuth(()=>setTimeout(async()=>{if(await refreshUser())render()},0));
 go('home')})();
